interface DashboardData {
  analytics: { views: number; visitors: number } | null
  notifications: { id: string; message: string; read: boolean }[] | null
  settings: { theme: string; language: string } | null
}

async function getDashboardData(): Promise<DashboardData> {
  try {
    const [analytics, notifications, settings] = await Promise.all([
      fetch('/api/analytics').then((r) => r.json()),
      fetch('/api/notifications').then((r) => r.json()),
      fetch('/api/settings').then((r) => r.json()),
    ])

    return { analytics, notifications, settings }
  } catch {
    return {
      analytics: { views: 0, visitors: 0 },
      notifications: [],
      settings: { theme: 'light', language: 'en' },
    }
  }
}

export default async function Dashboard() {
  const { analytics, notifications, settings } = await getDashboardData()

  return (
    <div>
      <h2>Dashboard</h2>
      <section>
        <h3>Analytics</h3>
        <p>Views: {analytics?.views ?? 0}</p>
        <p>Visitors: {analytics?.visitors ?? 0}</p>
      </section>
      <section>
        <h3>Notifications</h3>
        {notifications?.length ? (
          <ul>
            {notifications.map((n) => (
              <li key={n.id}>{n.message}</li>
            ))}
          </ul>
        ) : (
          <p>No notifications</p>
        )}
      </section>
      <section>
        <h3>Settings</h3>
        <p>Theme: {settings?.theme}</p>
        <p>Language: {settings?.language}</p>
      </section>
    </div>
  )
}

